//! Startup banner: the FalkorDB logo, printed to stdout when the module
//! loads, the way Redis and Valkey print theirs.
//!
//! The logo files next to this module are generated by
//! `build/banner/generate.py` from `build/banner/logo.png`; regenerate them
//! with that script rather than editing them.
//!
//! The banner is decoration, so it is printed only to a terminal and only in
//! a form the terminal can show:
//!
//! - stdout not a terminal (a log file, systemd, `--daemonize`, `docker run`
//!   without `-t`), `TERM` unset or `dumb`: nothing.
//! - Not a UTF-8 locale, or `TERM=linux` (the kernel console, whose fonts
//!   have no quadrant block glyphs): a one-line ASCII text banner, no logo.
//! - `NO_COLOR` set (<https://no-color.org>): the logo without colour.
//! - `COLORTERM` is `truecolor` or `24bit`: the logo in 24-bit colour.
//! - Otherwise: the logo in the xterm 256-colour palette.

use std::{
    ffi::CStr,
    fs::{File, OpenOptions},
    io::{IsTerminal, Write},
    os::{
        fd::{AsRawFd, RawFd},
        unix::fs::OpenOptionsExt,
    },
    thread,
    time::{Duration, Instant},
};

const TRUECOLOR: &str = include_str!("truecolor.ans");
const ANSI256: &str = include_str!("ansi256.ans");
const PLAIN: &str = include_str!("plain.txt");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Style {
    TrueColor,
    Ansi256,
    Plain,
    TextOnly,
}

/// Picks the banner style from the environment, read through `var` so the
/// choice is testable; `None` prints nothing.
fn style(var: impl Fn(&str) -> Option<String>) -> Option<Style> {
    let set = |name: &str| var(name).filter(|v| !v.is_empty());
    let term = set("TERM")?;
    if term == "dumb" {
        return None;
    }
    // POSIX precedence: the first of these that is set names the locale.
    let locale = ["LC_ALL", "LC_CTYPE", "LANG"]
        .into_iter()
        .find_map(set)
        .unwrap_or_default()
        .to_ascii_lowercase();
    if !(locale.contains("utf-8") || locale.contains("utf8")) || term == "linux" {
        return Some(Style::TextOnly);
    }
    if set("NO_COLOR").is_some() {
        return Some(Style::Plain);
    }
    match set("COLORTERM").as_deref() {
        Some("truecolor" | "24bit") => Some(Style::TrueColor),
        _ => Some(Style::Ansi256),
    }
}

fn render(
    style: Style,
    version: &str,
) -> String {
    match style {
        Style::TextOnly => format!("\nFalkorDB v{version} - https://falkordb.com\n\n"),
        Style::Plain => {
            format!("\n{PLAIN}\n  FalkorDB v{version} \u{b7} https://falkordb.com\n\n")
        }
        Style::TrueColor | Style::Ansi256 => {
            let logo = if style == Style::TrueColor {
                TRUECOLOR
            } else {
                ANSI256
            };
            format!("\n{logo}\n\x1b[2m  FalkorDB v{version} \u{b7} https://falkordb.com\x1b[0m\n\n")
        }
    }
}

/// How long to wait for the terminal to take one banner line before giving
/// up on the rest; a draining terminal takes a line in microseconds.
const DRAIN_WAIT: Duration = Duration::from_millis(100);

/// Prints the banner if stdout is a terminal that can show it.
///
/// The banner is several KB, more than a terminal's output queue holds. If
/// the terminal is not draining (the user pressed Ctrl-S, or nothing reads the
/// pty), a blocking write would stall `graph_init`, which runs on the server's
/// main thread at startup and on `MODULE LOAD`; and even a non-blocking write
/// would leave the queue full, so the server's next log line would stall
/// instead. So the banner goes out a line at a time through a fresh
/// non-blocking open of the terminal (a new file description: stdout's flags,
/// which the server shares, are untouched), and the next line is written only
/// once the queue has drained. If it does not drain within [`DRAIN_WAIT`],
/// the rest of the banner is dropped. Each line resets its own colour, so a
/// cut banner leaves no colour behind. Errors are ignored: the banner must
/// never fail or hold up the module load.
pub fn print() {
    if !std::io::stdout().is_terminal() {
        return;
    }
    let Some(style) = style(|name| std::env::var(name).ok()) else {
        return;
    };
    if let Some(mut tty) = reopen_nonblocking(libc::STDOUT_FILENO) {
        write_bounded(
            &mut tty,
            &render(style, env!("CARGO_PKG_VERSION")),
            DRAIN_WAIT,
        );
    }
}

/// Writes `text` to `tty` a line at a time, each line only once the previous
/// one has left the output queue; stops at the first line the terminal does
/// not take within `wait`. Returns whether all of `text` was written.
fn write_bounded(
    tty: &mut File,
    text: &str,
    wait: Duration,
) -> bool {
    text.split_inclusive('\n')
        .all(|line| tty.write_all(line.as_bytes()).is_ok() && drained(tty, wait))
}

/// Waits up to `wait` for the terminal's output queue to empty.
fn drained(
    tty: &File,
    wait: Duration,
) -> bool {
    let deadline = Instant::now() + wait;
    loop {
        let mut queued: libc::c_int = 0;
        // SAFETY: TIOCOUTQ stores the output queue length in the c_int it is
        // given; `tty` is an open terminal for the duration of the call.
        if unsafe { libc::ioctl(tty.as_raw_fd(), libc::TIOCOUTQ, &raw mut queued) } != 0 {
            return false;
        }
        if queued == 0 {
            return true;
        }
        if Instant::now() >= deadline {
            return false;
        }
        thread::sleep(Duration::from_millis(1));
    }
}

/// Opens the terminal `fd` refers to again, as a new file description that is
/// non-blocking and does not become the controlling terminal.
fn reopen_nonblocking(fd: RawFd) -> Option<File> {
    let mut name = [0 as libc::c_char; 256];
    // SAFETY: `name` is a writable buffer of the length passed; on success
    // ttyname_r leaves a NUL-terminated path in it.
    if unsafe { libc::ttyname_r(fd, name.as_mut_ptr(), name.len()) } != 0 {
        return None;
    }
    // SAFETY: ttyname_r succeeded, so `name` holds a NUL-terminated string.
    let path = unsafe { CStr::from_ptr(name.as_ptr()) }.to_str().ok()?;
    OpenOptions::new()
        .write(true)
        .custom_flags(libc::O_NONBLOCK | libc::O_NOCTTY)
        .open(path)
        .ok()
}

#[cfg(test)]
mod tests {
    use std::{
        fs::File,
        io::Read,
        os::fd::{FromRawFd, OwnedFd},
        thread,
        time::{Duration, Instant},
    };

    use super::{
        ANSI256, PLAIN, Style, TRUECOLOR, render, reopen_nonblocking, style, write_bounded,
    };

    fn env(vars: &[(&str, &str)]) -> impl Fn(&str) -> Option<String> {
        let vars: Vec<(String, String)> = vars
            .iter()
            .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
            .collect();
        move |name| vars.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
    }

    const UTF8: (&str, &str) = ("LANG", "en_US.UTF-8");

    #[test]
    fn no_banner_without_a_capable_term() {
        assert_eq!(style(env(&[UTF8])), None);
        assert_eq!(style(env(&[("TERM", ""), UTF8])), None);
        assert_eq!(style(env(&[("TERM", "dumb"), UTF8])), None);
    }

    #[test]
    fn text_only_without_utf8_or_on_the_linux_console() {
        assert_eq!(
            style(env(&[("TERM", "xterm-256color")])),
            Some(Style::TextOnly)
        );
        assert_eq!(
            style(env(&[("TERM", "xterm-256color"), ("LANG", "C")])),
            Some(Style::TextOnly)
        );
        assert_eq!(
            style(env(&[("TERM", "linux"), UTF8])),
            Some(Style::TextOnly)
        );
    }

    #[test]
    fn locale_follows_posix_precedence() {
        let term = ("TERM", "xterm-256color");
        assert_eq!(
            style(env(&[term, ("LC_ALL", "C"), UTF8])),
            Some(Style::TextOnly)
        );
        assert_eq!(
            style(env(&[term, ("LC_ALL", "en_US.UTF-8"), ("LANG", "C")])),
            Some(Style::Ansi256)
        );
        assert_eq!(
            style(env(&[
                term,
                ("LC_ALL", ""),
                ("LC_CTYPE", "C.utf8"),
                ("LANG", "C")
            ])),
            Some(Style::Ansi256)
        );
    }

    #[test]
    fn no_color_drops_colour() {
        let base = [("TERM", "xterm-256color"), UTF8, ("COLORTERM", "truecolor")];
        assert_eq!(
            style(env(&[base[0], base[1], base[2], ("NO_COLOR", "1")])),
            Some(Style::Plain)
        );
        // An empty NO_COLOR does not count, per no-color.org.
        assert_eq!(
            style(env(&[base[0], base[1], base[2], ("NO_COLOR", "")])),
            Some(Style::TrueColor)
        );
    }

    #[test]
    fn truecolor_only_when_advertised() {
        let term = ("TERM", "xterm-256color");
        assert_eq!(
            style(env(&[term, UTF8, ("COLORTERM", "truecolor")])),
            Some(Style::TrueColor)
        );
        assert_eq!(
            style(env(&[term, UTF8, ("COLORTERM", "24bit")])),
            Some(Style::TrueColor)
        );
        assert_eq!(style(env(&[term, UTF8])), Some(Style::Ansi256));
        assert_eq!(
            style(env(&[term, UTF8, ("COLORTERM", "yes")])),
            Some(Style::Ansi256)
        );
    }

    fn strip_sgr(s: &str) -> String {
        let mut out = String::new();
        let mut chars = s.chars();
        while let Some(c) = chars.next() {
            if c == '\x1b' {
                for c in chars.by_ref() {
                    if c == 'm' {
                        break;
                    }
                }
            } else {
                out.push(c);
            }
        }
        out
    }

    #[test]
    fn variants_are_the_same_80_column_logo() {
        assert_eq!(strip_sgr(TRUECOLOR), PLAIN);
        assert_eq!(strip_sgr(ANSI256), PLAIN);
        assert!(PLAIN.lines().all(|l| l.chars().count() <= 80));
        assert!(!PLAIN.contains('\x1b'));
        assert!(TRUECOLOR.contains("\x1b[38;2;"));
        assert!(ANSI256.contains("\x1b[38;5;") && !ANSI256.contains("\x1b[38;2;"));
    }

    #[test]
    fn rendered_banners_match_their_style() {
        let text = render(Style::TextOnly, "1.2.3");
        assert!(text.is_ascii() && text.contains("FalkorDB v1.2.3"));
        let plain = render(Style::Plain, "1.2.3");
        assert!(!plain.contains('\x1b') && plain.contains(PLAIN));
        assert!(render(Style::TrueColor, "1.2.3").contains(TRUECOLOR));
        assert!(render(Style::Ansi256, "1.2.3").contains(ANSI256));
    }

    /// A pseudo-terminal: the master end (what a terminal emulator reads) and
    /// the slave end (the server's stdout).
    fn pty() -> (File, OwnedFd) {
        let (mut master, mut slave) = (0, 0);
        // SAFETY: openpty writes two fds into the out-pointers; the name,
        // termios and winsize arguments may be NULL.
        let rc = unsafe {
            libc::openpty(
                &raw mut master,
                &raw mut slave,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                std::ptr::null_mut(),
            )
        };
        assert_eq!(rc, 0, "openpty failed");
        // SAFETY: both fds were just opened by openpty and are owned here.
        unsafe { (File::from_raw_fd(master), OwnedFd::from_raw_fd(slave)) }
    }

    fn banner() -> String {
        render(Style::TrueColor, "1.2.3")
    }

    #[test]
    fn whole_banner_reaches_a_draining_terminal() {
        let (mut master, slave) = pty();
        let banner = banner();
        let want = banner.len();
        let reader = thread::spawn(move || {
            // The pty turns each \n into \r\n on the way out.
            let mut got = Vec::new();
            let mut buf = [0u8; 4096];
            while got.iter().filter(|&&b| b != b'\r').count() < want {
                let n = master.read(&mut buf).expect("read pty");
                got.extend_from_slice(&buf[..n]);
            }
            got
        });
        let mut tty = reopen_nonblocking(std::os::fd::AsRawFd::as_raw_fd(&slave)).expect("reopen");
        assert!(write_bounded(&mut tty, &banner, Duration::from_secs(5)));
        let got: Vec<u8> = reader
            .join()
            .unwrap()
            .into_iter()
            .filter(|&b| b != b'\r')
            .collect();
        assert_eq!(String::from_utf8(got).unwrap(), banner);
    }

    #[test]
    fn a_paused_terminal_costs_one_wait_and_keeps_its_queue_free() {
        let (mut master, slave) = pty();
        // Ctrl-S: the terminal stops taking output, as when a user pauses it.
        std::io::Write::write_all(&mut master, b"\x13").unwrap();
        thread::sleep(Duration::from_millis(50));
        let mut tty = reopen_nonblocking(std::os::fd::AsRawFd::as_raw_fd(&slave)).expect("reopen");
        let wait = Duration::from_millis(100);
        let start = Instant::now();
        assert!(!write_bounded(&mut tty, &banner(), wait));
        let took = start.elapsed();
        assert!(took >= wait && took < wait * 5, "took {took:?}");
        // Only the first line was queued, so the server's own log lines
        // still fit instead of blocking.
        let mut queued: libc::c_int = 0;
        // SAFETY: TIOCOUTQ stores the queue length in the c_int it is given.
        let rc = unsafe {
            libc::ioctl(
                std::os::fd::AsRawFd::as_raw_fd(&slave),
                libc::TIOCOUTQ,
                &raw mut queued,
            )
        };
        assert_eq!(rc, 0);
        assert!(queued <= 2, "{queued} bytes queued");
    }
}
